package oepul.o6_10

import rego.v1

# Die Prüffolgen nennen nur durch die Eingabe belegte Sachverhalte.
# Bei Ermessensentscheidungen bleibt die konkrete AMA-Entscheidung offen.
administrative_findings contains {"rule_id": "o6_10.refusal", "outcome": "reject_current_year_and_reverse_contracts"} if {
	c := input.farm.oepul.control
	c.onsite_prevented
	c.force_majeure_or_exceptional == false
}

administrative_findings contains {"rule_id": "o6_10.late_evidence", "outcome": "document_missing", "document": e.id} if {
	some e in input.farm.oepul.requested_evidence
	e.received_on == null
	date_ns(input.farm.oepul.as_of) > date_ns(e.effective_due_on)
}

administrative_findings contains {"rule_id": "o6_10.late_evidence", "outcome": "document_late", "document": e.id} if {
	some e in input.farm.oepul.requested_evidence
	date_ns(e.received_on) > date_ns(e.effective_due_on)
}

administrative_findings contains {"rule_id": "o6_10.third_party", "parcel_id": p.parcel_id, "outcome": "retain_and_present_evidence"} if {
	some p in input.land.parcels
	crop_group(p)
	p.oepul.in_at
	"third_party" in p.oepul.op_reasons
	p.oepul.third_party_evidence_available == false
}

administrative_findings contains {"rule_id": "o6_10.trial", "parcel_id": p.parcel_id, "missing": missing} if {
	some p in input.land.parcels
	crop_group(p)
	p.oepul.in_at
	p.oepul.trial_prevents_compliance
	missing := {key | some key in {"written_approval", "trial_type", "area", "location"}; p.oepul.trial_documentation[key] == false}
	count(missing) > 0
}

administrative_findings contains {"rule_id": "o6_10.trial", "parcel_id": p.parcel_id, "outcome": "code_VF_required"} if {
	some p in input.land.parcels
	crop_group(p)
	p.oepul.in_at
	p.oepul.trial_prevents_compliance
	is_array(p.oepul.codes)
	not "VF" in p.oepul.codes
}

administrative_findings contains {"rule_id": "o6_10.transfer", "parcel_id": p.parcel_id, "outcome": "report_and_code_OP"} if {
	some p in input.land.parcels
	crop_group(p)
	p.oepul.in_at
	p.oepul.transferred_during_year
	p.oepul.transferee_continued_to_year_end == false
}

land_issue[f.parcel_id] contains "transfer" if {
	some f in administrative_findings
	f.rule_id == "o6_10.transfer"
}

permanent_payment_review(context) if context.force_majeure_or_exceptional

permanent_payment_review(context) if {
	year_of(context.event_on) == input.farm.year
	context.event_on > sprintf("%d-04-15", [input.farm.year])
}

permanent_payment_review(context) if {
	year_of(context.event_on) == input.farm.year
	date_ns(context.event_on) > date_ns(context.cover_sown_on)
}

reported_circumstance(p, kind) := c if {
	crop_group(p)
	p.oepul.in_at
	c := p.oepul.changed_circumstances
	c.kind == kind
	c.outside_control
	c.reported_as_required
}

circumstance_review contains {"parcel_id": p.parcel_id, "rule_id": "o6_10.permanent", "outcome": "early_termination_without_recovery_may_be_granted"} if {
	some p in input.land.parcels
	c := reported_circumstance(p, "permanent")
	c.compliance_impossible
}

circumstance_review contains {"parcel_id": p.parcel_id, "rule_id": "o6_10.permanent", "outcome": "payment_in_event_year_may_be_granted"} if {
	some p in input.land.parcels
	c := reported_circumstance(p, "permanent")
	year_of(c.event_on) == input.farm.year
	c.compliance_impossible
	permanent_payment_review(c)
}

temporary_basis(c) if c.compliance_impossible
temporary_basis(c) if c.area_relocated

circumstance_review contains {"parcel_id": p.parcel_id, "rule_id": "o6_10.temporary", "outcome": "recovery_may_be_waived"} if {
	some p in input.land.parcels
	c := reported_circumstance(p, "temporary")
	temporary_basis(c)
}

circumstance_review contains {"parcel_id": p.parcel_id, "rule_id": "o6_10.temporary", "outcome": "payment_in_affected_year_may_be_granted"} if {
	some p in input.land.parcels
	c := reported_circumstance(p, "temporary")
	temporary_basis(c)
	true in [object.get(c, "force_majeure_or_exceptional", null), object.get(c, "conditions_met_on_changed_area", null)]
}

package oepul.o6_10

import rego.v1

farm_conflicts contains {"left": row.left, "right": row.right, "rule_id": "o6_10.combo_all_farm"} if {
	some row in t.farm_conflicts
	input.farm.year >= row.from_year
	active := array.concat(input.farm.oepul.active_measures, object.get(input.farm.oepul, "active_options", []))
	row.left in active
	row.right in active
	pair_excluded(row)
}

pair_excluded(row) if row.partial_organic_exception == false
pair_excluded(_) if input.farm.oepul.partial_organic == false

parcel_combination_conflicts contains {"parcel_id": term.parcel_id, "other": term.other, "rule_id": "o6_10.combine"} if {
	some term in combination_terms
	term.cell.mark == ""
}

parcel_combination_conflicts contains {"parcel_id": p.parcel_id, "other": "K20", "rule_id": "o6_10.k20_combination"} if {
	some p in input.land.parcels
	p.oepul.claimed_for_measure
	input.farm.year in {2023, 2024}
	"K20" in p.oepul.same_area_measures
}

requires_option_application(measure, option) if {
	some row in t.application_options
	measure in row.measures
	row.option == option
}

catch_crop_variant(number, year) := row if {
	some row in t.catch_crop_variants
	row.variant == number
	year >= row.first_year
	year <= row.last_year
}

management_exemption(use, measure, year) if {
	some row in t.management_exemptions
	row.use == use
	measure in row.measures
	year >= row.first_year
	year <= row.last_year
}

public_exception(measure, year) if {
	some row in t.public_exceptions
	row.measure == measure
	year >= row.first_year
	year <= row.last_year
}

annually_variable_units(measure, use) if {
	some row in t.variable_units
	row.measure == measure
	row.use in {"all", use}
}

package oepul.o6_10

import rego.v1

# The event date is the actual event triggering re-establishment.
reseed_due(e) := sprintf("%d-05-15", [year_of(e.date) + 1]) if {
	e.kind == "clearing"
	e.date > sprintf("%d-09-15", [year_of(e.date)])
} else := substring(time.format(min({date_ns(e.date) + (56 * 86400000000000), date_ns(sprintf("%d-10-01", [year_of(e.date)]))})), 0, 10) if {
	e.kind in {"break", "clearing", "planting"}
}

covered_by_deadline(c, day) if {
	some e in c.events
	e.date <= day
	day <= reseed_due(e)
	e.reseeded_on == null
}

covered_by_deadline(c, day) if {
	some e in c.events
	e.date <= day
	day < e.reseeded_on
	day <= reseed_due(e)
}

proper_sowing(q) if {
	q.seedbed
	q.timing
	q.rate
	q.depth
	q.equipment
	q.crops
}

drought_cover(p, o) if {
	input.farm.year == 2026
	year_of(o.date) == 2026
	p.oepul.in_at
	proper_sowing(o.sowing_quality)
	o.dry_emergence_gap
}

drought_grain(p, o) if {
	input.farm.year == 2026
	year_of(o.date) == 2026
	p.oepul.in_at
	proper_sowing(o.sowing_quality)
	o.excess_due_to_volunteer_grain_and_dry_germination
}

grazing_allowed(g) if {
	g.species == "sheep"
	g.extensive_density
	g.main_crop_primary
}

grazing_allowed(g) if {
	g.species == "poultry"
	g.year_round == false
}

requires_cover(p) if crop_group(p) in {"orchard", "hop"}

requires_cover(p) if {
	crop_group(p) == "vineyard"
	p.oepul.wine_terrace == false
}

requires_cover(p) if {
	crop_group(p) == "vineyard"
	p.oepul.wine_terrace
	is_number(p.oepul.section_slope_pct)
	p.oepul.section_slope_pct < 25
}

# point-in-time observations across the year, including peak cereal/maize share
observation(p, o) if {
	requires_cover(p)
	year_of(o.date) == input.farm.year
	not covered_by_deadline(p.operations.erosion, o.date)
}

width_limit(p) := 80 if crop_group(p) == "vineyard"

else := 100 if crop_group(p) in {"hop", "orchard"}

cover_issue[p.parcel_id] contains "alleys" if {
	some p in input.land.parcels
	some o in p.operations.erosion.observations
	observation(p, o)
	o.special_system_width_impossible == false
	o.all_alleys_covered == false
	not drought_cover(p, o)
}

cover_issue[p.parcel_id] contains "width" if {
	some p in input.land.parcels
	some o in p.operations.erosion.observations
	observation(p, o)
	o.special_system_width_impossible == false
	is_number(o.open_strip_cm)
	o.open_strip_cm > width_limit(p)
}

cover_issue[p.parcel_id] contains "special_rows" if {
	some p in input.land.parcels
	some o in p.operations.erosion.observations
	observation(p, o)
	o.special_system_width_impossible
	is_number(o.covered_pct)
	o.covered_pct < 60
	not drought_cover(p, o)
}

cover_issue[p.parcel_id] contains "sowing" if {
	some p in input.land.parcels
	requires_cover(p)
	c := p.operations.erosion
	c.origin == "sown"
	is_number(c.winter_hardy_partners)
	c.winter_hardy_partners < 3
}

cover_issue[p.parcel_id] contains "mulch" if {
	some p in input.land.parcels
	requires_cover(p)
	p.operations.erosion.origin == "organic_mulch"
}

cover_issue[p.parcel_id] contains "spontaneous" if {
	some p in input.land.parcels
	requires_cover(p)
	p.operations.erosion.origin == "spontaneous"
}

cover_issue[p.parcel_id] contains "pure_grain" if {
	some p in input.land.parcels
	requires_cover(p)
	c := p.operations.erosion
	is_cereal(c.pure_seed)
	lower(c.pure_seed) != "grünschnittroggen"
}

cover_issue[p.parcel_id] contains "pure_grain" if {
	some p in input.land.parcels
	requires_cover(p)
	c := p.operations.erosion
	lower(c.pure_seed) == "grünschnittroggen"
	c.authorised_green_rye == false
}

cover_issue[p.parcel_id] contains "pure_grain" if {
	some p in input.land.parcels
	requires_cover(p)
	lower(p.operations.erosion.pure_seed) == "mais"
}

# Percentages are absolute shares of the stand at the same observation.
cover_issue[p.parcel_id] contains "share" if {
	some p in input.land.parcels
	some o in p.operations.erosion.observations
	requires_cover(p)
	year_of(o.date) == input.farm.year
	(o.cereal_pct + o.maize_pct) - o.oat_spring_barley_nurse_pct > 50
	not drought_grain(p, o)
}

cover_issue[p.parcel_id] contains "tillage" if {
	some p in input.land.parcels
	requires_cover(p)
	some e in p.operations.erosion.tillage
	year_of(e.date) == input.farm.year
	e.destroyed_cover
	e.followed_by_reestablishment == false
}

cover_issue[p.parcel_id] contains "renewal" if {
	some p in input.land.parcels
	requires_cover(p)
	count([1 | some e in p.operations.erosion.events; e.kind == "break"; year_of(e.date) == input.farm.year]) > 1
}

cover_issue[p.parcel_id] contains "deadline" if {
	some p in input.land.parcels
	requires_cover(p)
	some e in p.operations.erosion.events
	due := reseed_due(e)
	year_of(due) == input.farm.year
	is_string(e.reseeded_on)
	e.reseeded_on > due
}

cover_issue[p.parcel_id] contains "deadline" if {
	some p in input.land.parcels
	requires_cover(p)
	some e in p.operations.erosion.events
	due := reseed_due(e)
	year_of(due) == input.farm.year
	e.reseeded_on == null
	input.farm.oepul.as_of > due
}

cover_issue[p.parcel_id] contains "use" if {
	some p in input.land.parcels
	p.operations.erosion.mowings_removed == true
}

cover_issue[p.parcel_id] contains "use" if {
	some p in input.land.parcels
	p.operations.erosion.other_use == true
}

cover_issue[p.parcel_id] contains "grazing" if {
	some p in input.land.parcels
	some g in p.operations.erosion.grazing
	not g.species in {"sheep", "poultry"}
	is_string(g.species)
}

cover_issue[p.parcel_id] contains "grazing" if {
	some p in input.land.parcels
	some g in p.operations.erosion.grazing
	g.species == "sheep"
	false in [object.get(g, "extensive_density", null), object.get(g, "main_crop_primary", null)]
}

cover_issue[p.parcel_id] contains "grazing" if {
	some p in input.land.parcels
	some g in p.operations.erosion.grazing
	g.species == "poultry"
	g.year_round
}

cover_issue[p.parcel_id] contains "psm" if {
	some p in input.land.parcels
	p.operations.erosion.psm_on_living_alley_cover == true
}

cover_issue[p.parcel_id] contains "mechanical" if {
	some p in input.land.parcels
	p.operations.erosion.nonmechanical_termination == true
}

missing_cover_records(record, events) := {row.field |
	some row in t.cover_record_fields
	row.event in array.concat(["all"], events)
	not filled(record, row.field)
}

filled(record, key) if {
	v := record[key]
	v != null
	v != ""
	v != false
}

missing_application_records(a) := {f | some f in t.application_record_fields; not filled(a, f)}

park_block(p) if p.oepul.national_park in {"Neusiedlersee", "Donau-Auen"}
park_block(p) if p.oepul.park_relevant_restrictions == true

land_issue[p.parcel_id] contains "park" if {
	some p in input.land.parcels
	park_block(p)
}

land_issue[p.parcel_id] contains "cultivation" if {
	some p in input.land.parcels
	some key in {"proper_planting", "annual_care", "harvest_removed"}
	p.oepul[key] == false
}

land_issue[p.parcel_id] contains "ineligible" if {
	some p in input.land.parcels
	some key in {"correct_reference", "claimed_for_measure", "active_production", "mainly_agricultural"}
	p.oepul[key] == false
}

land_issue[p.parcel_id] contains "ineligible" if {
	some p in input.land.parcels
	p.oepul.land_exclusion in {"other_area", "gloez_element", "palm_catkins", "short_rotation", "nursery", "energy_wood"}
}

land_issue[p.parcel_id] contains "trial" if {
	some p in input.land.parcels
	"VF" in p.oepul.codes
}

land_issue[p.parcel_id] contains "trial" if {
	some p in input.land.parcels
	p.oepul.trial_prevents_compliance == true
}

land_issue[p.parcel_id] contains "op" if {
	some p in input.land.parcels
	"OP" in p.oepul.codes
}

land_issue[p.parcel_id] contains "op" if {
	some p in input.land.parcels
	p.oepul.measure_specific_op == true
}

land_issue[p.parcel_id] contains "stock" if {
	some p in input.land.parcels
	p.crop.crop_category == "orchard"
	p.oepul.quality_planting_stock == false
}

parcel_findings contains {"parcel_id": p.parcel_id, "rule_id": concat("", ["o6_10.", key])} if {
	some p in input.land.parcels
	p.oepul.in_at
	crop_group(p)
	some key in cover_issue[p.parcel_id]
}

parcel_findings contains {"parcel_id": p.parcel_id, "rule_id": concat("", ["o6_10.", key])} if {
	some p in input.land.parcels
	p.oepul.in_at
	crop_group(p)
	some key in land_issue[p.parcel_id]
}

# Die Feststellung ist an den konkreten Bestandsmangel und die Beobachtung gebunden.
automatic_force_majeure contains {"parcel_id": p.parcel_id, "date": o.date, "rule_id": "o6_10.drought_cover", "individual_report_required": false} if {
	some p in input.land.parcels
	some o in p.operations.erosion.observations
	observation(p, o)
	cover_gap(o)
	drought_cover(p, o)
}

cover_gap(o) if {
	o.special_system_width_impossible == false
	o.all_alleys_covered == false
}

cover_gap(o) if {
	o.special_system_width_impossible
	is_number(o.covered_pct)
	o.covered_pct < 60
}

automatic_force_majeure contains {"parcel_id": p.parcel_id, "date": o.date, "rule_id": "o6_10.drought_grain", "individual_report_required": false} if {
	some p in input.land.parcels
	requires_cover(p)
	some o in p.operations.erosion.observations
	(o.cereal_pct + o.maize_pct) - o.oat_spring_barley_nurse_pct > 50
	drought_grain(p, o)
}

package oepul.o6_10

import rego.v1

t := data.o6_10_tables

# A crop group is a legal classification. A catalogue name can refine orchard,
# including grouped entries such as related Aronia cultivars.
crop_group(p) := p.crop.crop_category if {
	p.crop.crop_category in {"vineyard", "hop"}
	p.oepul.excluded_crop_use == false
} else := "orchard" if {
	p.crop.crop_category == "orchard"
	p.oepul.excluded_crop_use == false
	name := fruit_name(p)
	some f in t.fruit
	lower(name) == lower(f.name)
	input.farm.year >= f.first_year
}

is_cereal(name) if {
	some x in t.cereals
	lower(name) == lower(x)
}

crop_list(name) := t[name] if name in {"fodder", "vegetables", "non_cereals", "div_variants"}

# An incomplete list must not establish loss of the contract.
classification_known(p) if p.oepul.in_at == false
classification_known(p) if p.oepul.in_mfa == false
classification_known(p) if p.oepul.excluded_crop_use == true

classification_known(p) if {
	is_string(p.crop.crop_category)
	not p.crop.crop_category in {"vineyard", "hop", "orchard"}
}

classification_known(p) if {
	p.oepul.in_at == true
	p.oepul.in_mfa == true
	p.oepul.excluded_crop_use == false
	p.crop.crop_category in {"vineyard", "hop"}
	is_number(p.area_ha)
	p.area_ha >= 0
}

classification_known(p) if {
	p.oepul.in_at == true
	p.oepul.in_mfa == true
	p.oepul.excluded_crop_use == false
	p.crop.crop_category == "orchard"
	orchard_classification_known(p)
	is_number(input.farm.year)
	is_number(p.area_ha)
	p.area_ha >= 0
}

orchard_classification_known(p) if is_string(p.oepul.fruit_group)

orchard_classification_known(p) if {
	some f in t.fruit
	lower(p.crop.crop_name) == lower(f.name)
}

known_measure_area_ha := sum([p.area_ha |
	some p in input.land.parcels
	p.oepul.in_at == true
	p.oepul.in_mfa == true
	crop_group(p)
	is_number(p.area_ha)
	p.area_ha >= 0
]) if {
	is_array(input.land.parcels)
}

measure_area_ha := known_measure_area_ha if {
	is_array(input.land.parcels)
	every p in input.land.parcels { classification_known(p) }
}

meets_measure_minimum if known_measure_area_ha >= 0.5

else := false if measure_area_ha < 0.5

farm_minimum if {
	is_number(input.farm.oepul.first_year)
	input.farm.oepul.first_year < input.farm.year
} else if {
	input.farm.oepul.first_year == input.farm.year
	is_number(input.land.mfa_protected_ha)
	input.land.mfa_protected_ha >= 0.5
} else := result if {
	input.farm.oepul.first_year == input.farm.year
	is_number(input.land.mfa_qualifying_ha)
	result := input.land.mfa_qualifying_ha >= 1.5
	any_lower_bound_known(result)
}

any_lower_bound_known(true) := true
any_lower_bound_known(false) if is_number(input.land.mfa_protected_ha)

public_entity(a) if a.kind == "public"

public_entity(a) if {
	is_number(a.public_share_pct)
	a.public_share_pct > 25
}

public_entity(a) if a.equivalent_or_indirect_public_control == true

permitted_form(a) if {
	a.kind in {"individual", "registered_partnership", "legal_person", "association", "public"}
	public_exception("10", input.farm.year)
}

permitted_form(a) if {
	input.farm.year >= 2025
	a.kind == "individual"
}

permitted_form(a) if {
	input.farm.year >= 2025
	a.kind in {"individual", "registered_partnership", "legal_person", "association"}
	a.equivalent_or_indirect_public_control == false
	is_number(a.public_share_pct)
	not public_entity(a)
}

applicant_allowed if {
	a := input.farm.oepul.applicant
	a.active_farmer
	a.agricultural_activity
	a.own_name_and_account
	a.disposal_rights
	permitted_form(a)
}

date_ns(date) := time.parse_rfc3339_ns(concat("", [date, "T00:00:00Z"])) if is_string(date)
year_of(date) := time.date(date_ns(date))[0]

withdrawn(a) if year_of(a.withdrawn_on) == input.farm.year
no_withdrawal(a) if a.withdrawn_on == null
no_withdrawal(a) if year_of(a.withdrawn_on) > input.farm.year

# Fristen knüpfen an den Kontrollzeitpunkt an. Bei gleichem Kalendertag
# lässt sich die Reihenfolge mit Datumsangaben allein nicht ermitteln.
withdrawal_timing(a) := "after_control" if {
	withdrawn(a)
	some key in {"control_announced_on", "onsite_on", "administrative_result_on"}
	date_ns(a[key]) < date_ns(a.withdrawn_on)
} else := "clear" if {
	withdrawn(a)
	every key in {"control_announced_on", "onsite_on", "administrative_result_on"} {
		control_after_or_absent(a[key], a.withdrawn_on)
	}
} else := "unresolved" if withdrawn(a)

control_after_or_absent(control, _) if control == null
control_after_or_absent(control, day) if date_ns(control) > date_ns(day)

contract_route := "withdrawal_after_control" if {
	withdrawal_timing(input.farm.oepul.contract) == "after_control"
} else := "withdrawal_timing_unresolved" if {
	withdrawal_timing(input.farm.oepul.contract) == "unresolved"
} else := "withdrawn" if {
	withdrawn(input.farm.oepul.contract)
} else := "below_minimum" if {
	meets_measure_minimum == false
} else := "takeover" if {
	takeover_allowed
	no_withdrawal(input.farm.oepul.contract)
	input.farm.oepul.contract.annual_mfa_with_units
	meets_measure_minimum
} else := "continuation" if {
	a := input.farm.oepul.contract
	a.previous_active
	a.annual_mfa_with_units
	no_withdrawal(a)
	meets_measure_minimum
	input.farm.year in numbers.range(2023, 2028)
} else := "new_application" if {
	a := input.farm.oepul.contract
	a.previous_active == false
	a.annual_mfa_with_units
	no_withdrawal(a)
	ordinary_entry_timely(a)
	meets_measure_minimum
}

takeover_allowed if {
	tariff_year(input.farm.year)
	a := input.farm.oepul.takeover
	a.previously_participating == false
	a.mfa_online
	a.ama_approved
	a.transferred_ha > 0
	a.additional_ha >= 0
	a.additional_ha <= a.transferred_ha * 0.5
	year_of(a.applied_on) == input.farm.year
	a.applied_on <= takeover_cutoff(input.farm.year)
}

takeover_cutoff(y) := sprintf("%d-04-17", [y]) if y in {2023, 2028}

else := sprintf("%d-04-15", [y])

terrace(p) if {
	crop_group(p) == "vineyard"
	p.oepul.wine_terrace
	is_number(p.oepul.section_slope_pct)
	p.oepul.section_slope_pct >= 25
}

fruit_name(p) := p.oepul.fruit_group if is_string(p.oepul.fruit_group)

else := p.crop.crop_name

# Die Einstiegsfrist betrifft den regulären Neuantrag. Die genehmigte
# Übernahme hat eigene Voraussetzungen.
ordinary_entry_timely(a) := false if {
	a.previous_active == false
	is_number(input.farm.year)
	not input.farm.year in numbers.range(2023, 2027)
} else := valid if {
	a.previous_active == false
	y := year_of(a.applied_on)
	valid := y == (input.farm.year - 1)
	a.applied_on >= "2022-11-02"
} else := false if {
	a.previous_active == false
	date_ns(a.applied_on) < date_ns("2022-11-02")
}

contract_period(y) := {"from": sprintf("%d-01-01", [y]), "through": sprintf("%d-12-31", [y])} if tariff_year(y)

package oepul.o6_10

import rego.v1

# Tarifauskünfte vor Modulation, Obergrenze und Sanktionen.
tariff_year(y) if {
	y >= 2023
	y <= 2028
}

slope_match(row, _) if row.slope_from == null

slope_match(row, s) if {
	is_number(s)
	row.slope_from != null
	s >= row.slope_from
	row.slope_below == null
}

slope_match(row, s) if {
	is_number(s)
	row.slope_from != null
	is_number(row.slope_below)
	s >= row.slope_from
	s < row.slope_below
}

amounts(row, y) := row.band if y <= 2024

else := [row.fixed, row.fixed]

base_rate(p) := amounts(row, input.farm.year) if {
	tariff_year(input.farm.year)
	some row in t.rates
	row.component == "base"
	row.crop == crop_group(p)
	slope_match(row, object.get(p, "slope_percent", null))
}

qualifying_application(a) if {
	a.kind in {"organism", "pheromone"}
	year_of(a.date) == input.farm.year
	a.replaces_psm
	a.register_rate_met
}

supplement_parcels contains p.parcel_id if {
	some p in input.land.parcels
	p.oepul.in_mfa
	p.oepul.in_at
	p.oepul.claimed_for_measure
	crop_group(p)
	"EOP" in p.oepul.codes
	input.farm.oepul.organisation_program == false
	some a in p.operations.erosion.applications
	qualifying_application(a)
}

supplement_factor := 0.5 if {
	some m in input.farm.oepul.active_measures
	m in {"1B", "1B-Teilbetrieb", "12"}
} else := 1 if is_array(input.farm.oepul.active_measures)

supplement_rate(p) := [r[0] * supplement_factor, r[1] * supplement_factor] if {
	tariff_year(input.farm.year)
	p.parcel_id in supplement_parcels
	some row in t.rates
	row.component == "eop"
	row.crop == crop_group(p)
	r := amounts(row, input.farm.year)
}

combination(row, column) := cell if {
	some cell in t.combinations
	cell.row == row
	cell.column == column
}

combination_note(n) := t.matrix_notes[n - 1] if n in {1, 2, 3, 4}

# Gewichteter Faktor für die Heimfläche. Keine Rundung von Zwischenergebnissen.
tier_area(ha, row) := max([0, ha - row.start]) if row.end == null

else := max([0, min([ha, row.end]) - row.start])

modulation_factor(ha) := sum([amount | some row in t.modulation; amount := tier_area(ha, row) * row.factor]) / ha if {
	is_number(ha)
	ha > 0
}

home_modulation := modulation_factor(input.land.mfa_home_ha)

cap_terms(group, y) := row if {
	some row in t.caps
	row.group == group
	y >= row.first_year
	y <= row.last_year
}

cap_total(group, y, rates) := min([sum(included), cap.eur_ha]) + sum(excluded) if {
	cap := cap_terms(group, y)
	included := [amount | some m, amount in rates; not m in cap.excluded]
	excluded := [amount | some m, amount in rates; m in cap.excluded]
}

deduction_order := t.deductions
sanction_options(y) := {s.stage: s.through_2026 | some s in t.sanctions} if y < 2027

else := {s.stage: s.from_2027 | some s in t.sanctions}

switch_targets(origin, y) := row.destinations if {
	some row in t.switches
	row.origin == origin
	y >= 2023
	y <= row.last_year
}

arable_drought_region(state, district, as_of) if {
	year_of(as_of) == 2026
	some row in t.arable_regions
	row.state == state
	row.district in {"*", district}
	row.notice <= as_of
}

payment_parameters.home_modulation := home_modulation
payment_parameters.transfer_due := sprintf("%d-06-30", [input.farm.year + 1]) if tariff_year(input.farm.year)

payment_parameters.advance_max_eur := expected * 0.75 if {
	input.farm.oepul.payment.administrative_checks_completed
	expected := input.farm.oepul.payment.expected_eur
	is_number(expected)
	expected >= 0
}

payment_parameters.waiver_possible := amount <= 50 if {
	amount := input.farm.oepul.payment.calculated_eur
	is_number(amount)
	amount >= 0
}

# Vollständige, bereits modulierte Beträge je Maßnahme einschließlich
# umgelegter LSE. Mehrere Komponenten einer Maßnahme werden summiert.
payment_parameters.parcel_caps[p.parcel_id] := cap_total(group, input.farm.year, rates) if {
	some p in input.land.parcels
	group := p.oepul.payment_cap_group
	rows := p.oepul.modulated_eur_ha_by_measure
	is_array(rows)
	every row in rows {
		is_string(row.measure)
		is_number(row.eur_ha)
		row.eur_ha >= 0
	}
	rates := {m: sum([r.eur_ha | some r in rows; r.measure == m]) | some row in rows; m := row.measure}
}

